    from math import sin, cos, radians, pi
    from shapely.geometry import Polygon, Point

    def distance(p1, p2):
        return ((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2) ** 0.5

    def rotate_point(point, degrees):
        angle = radians(degrees)
        x = point[0] * cos(angle) - point[1] * sin(angle)
        y = point[0] * sin(angle) + point[1] * cos(angle)
        return (x, y)

    def rotate_polygon(vertices, degrees):
        return [rotate_point(vertex, degrees) for vertex in vertices]

    def area(polygon):
        x = [p[0] for p in polygon.exterior.coords]
        y = [p[1] for p in polygon.exterior.coords]
        return abs(sum(x[i] * y[i + 1] - x[i + 1] * y[i] for i in range(len(x) - 1)) / 2.0)

