        for point in polygon1.exterior.coords:
            if not polygon2.contains(Point(point)):
                return False
        return True

    def is_fully_outside(polygon1, polygon2):
        for point in polygon2.exterior.coords:
            if polygon1.contains(Point(point)):
                return False
        return True

